actualDictionaries.fvSchemes:
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    location "system";
    object fvSchemes;
}

ddtSchemes { default steadyState; }
gradSchemes { default cellLimited leastSquares 1; }
divSchemes { default none; div(phi,U) bounded Gauss linearUpwind grad(U); div((nuEff*dev2(T(grad(U))))) Gauss linear; }
laplacianSchemes { default Gauss linear limited 0.5; }
interpolationSchemes { default linear; }
snGradSchemes { default limited 0.5; }
wallDist { method meshWave; }

actualDictionaries.fvSolution:
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    location "system";
    object fvSolution;
}

solvers
{
 p { solver PCG; preconditioner DIC; tolerance 1e-11; relTol 0; maxIter 3000; }
 U { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-10; relTol 0; }
}
SIMPLE { nNonOrthogonalCorrectors 3; pRefCell 0; pRefValue 0; residualControl { p 1e-8; U 1e-8; } }
relaxationFactors { fields { p 0.25; } equations { U 0.6; } }

actualDictionaries.controlDict:
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    location "system";
    object controlDict;
}

application simpleFoam;
startFrom startTime; startTime 0; stopAt endTime; endTime 16000; deltaT 1;
writeControl timeStep; writeInterval 16000; purgeWrite 1; writeFormat ascii; writePrecision 17; writeCompression off;
timeFormat general; timePrecision 10; runTimeModifiable false;
functions { wallLoads { type forces; libs (forces); patches (cylinder); rho rhoInf; rhoInf 1; CofR (0 0 0); writeControl timeStep; writeInterval 1; log false; } }

